const body = $input.first()?.json?.body ?? {};

const orderCode = String(body.orderCode ?? '')
  .trim()
  .toLowerCase();

const phone = String(body.phone ?? '').trim();
const digits = phone.replace(/\D/g, '');

// Validate order code: 6 digits followed by -c
if (!/^\d{6}-c$/.test(orderCode)) {
  return [{
    json: {
      valid: false,
      success: false,
      message: 'كود الطلب غير صحيح.'
    }
  }];
}

// Validate Egyptian mobile number
if (!/^01[0125]\d{8}$/.test(digits)) {
  return [{
    json: {
      valid: false,
      success: false,
      message: 'رقم الموبايل غير صحيح.'
    }
  }];
}

return [{
  json: {
    valid: true,
    orderCode,
    phone: digits
  }
}];

const input = $input.first().json;
const order = input.order;

if (!input.success || !order) {
  return [{
    json: {
      success: false,
      message: input.message || 'لم يتم العثور على الطلب'
    }
  }];
}

const cakeImages = Array.isArray(order.images?.cake)
  ? order.images.cake
  : [];

const depositImages = Array.isArray(order.images?.deposit)
  ? order.images.deposit
  : [];

const allImages = [
  ...cakeImages,
  ...depositImages
];

// لا توجد صور في الطلب
if (allImages.length === 0) {
  return [{
    json: {
      ...order,
      noImages: true,
      images: {
        cake: [],
        deposit: []
      }
    }
  }];
}

// كل صورة تصبح Item مستقل
return allImages.map(image => ({
  json: {
    ...order,
    image,
    objectKey: image.objectKey
  }
}));

const items = $input.all();

if (items.length === 0) {
  return [];
}

const firstJson = items[0].json;

// الحفاظ على بيانات الطلب
const {
  image,
  objectKey,
  images,
  cakeImages,
  depositImages,
  ...order
} = firstJson;

const downloadedImages = [];

for (let index = 0; index < items.length; index++) {
  const item = items[index];

  // تحديد اسم الـBinary Property تلقائيًا
  const binaryProperty = Object.keys(item.binary ?? {})[0];

  if (!binaryProperty) {
    throw new Error(
      `الصورة رقم ${index + 1}: لا يوجد Binary Data في المدخلات`
    );
  }

  const binaryData = item.binary[binaryProperty];

  const buffer = await this.helpers.getBinaryDataBuffer(
    index,
    binaryProperty
  );

  // بيانات الصورة الأصلية
  const imageInfo = item.json.image ?? item.json;

  downloadedImages.push({
    ...imageInfo,
    dataUrl: `data:${binaryData.mimeType};base64,${buffer.toString('base64')}`
  });
}

return [
  {
    json: {
      ...order,
      images: downloadedImages
    }
  }
];
